package dashboard

import (
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
// the detail endpoint returns, so a huge file cannot bloat a response.
const maxDocBytes = 128 * 1024

// apiServer holds the request-independent state for the JSON API.
type apiServer struct {
	root    string
	version string
}

// fileDoc is a text document surfaced in an integration's detail view.
type fileDoc struct {
	Name    string `json:"name"`
	Content string `json:"content"`
}

// integrationSummary is a scaffold entry plus the coordinates the sidebar
// tree groups by: Name is the directory that carries the .intropy record,
// System is that directory's parent and Domain the system's parent. System
// is empty when the integration sits directly under the workspace root, and
// Domain is empty when the system does.
type integrationSummary struct {
	template.ScaffoldEntry
	Name   string `json:"name"`
	System string `json:"system,omitempty"`
	Domain string `json:"domain,omitempty"`
}

// integrationDetail is a single integration plus best-effort, on-disk
// enrichment. Every enrichment field is optional and absent when the
// corresponding file or directory does not exist.
type integrationDetail struct {
	integrationSummary
	Agents        *fileDoc        `json:"agents,omitempty"`
	Readme        *fileDoc        `json:"readme,omitempty"`
	Components    []DaprComponent `json:"components,omitempty"`
	PipelineSteps []string        `json:"pipelineSteps,omitempty"`
}

// newHandler wires the API routes and the SPA static handler onto a mux.
func newHandler(root, version string) (http.Handler, error) {
	api := &apiServer{root: root, version: version}
	static, err := staticHandler()
	if err != nil {
		return nil, err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", api.health)
	mux.HandleFunc("GET /api/integrations", api.listIntegrations)
	mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
	mux.HandleFunc("GET /api/flow", api.flow)
	mux.Handle("/", static)
	return mux, nil
}

func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{
		"status":  "ok",
		"version": s.version,
	})
}

// listIntegrations mirrors `int list -o json` — the same scaffold entries in
// the same order — with the derived name/system fields added on top and each
// Path normalized to a root-relative identifier. The response is always an
// array (never null) even when empty.
func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
	entries, _ := template.ListScaffolds(s.root)
	summaries := make([]integrationSummary, 0, len(entries))
	for _, e := range entries {
		summaries = append(summaries, s.summarize(e))
	}
	writeJSON(w, http.StatusOK, summaries)
}

// summarize derives an entry's tree coordinates from its path. The workspace
// root itself never counts as a system or domain, so an integration
// scaffolded at the root has neither and one directly under the root has a
// system but no domain. The served Path is made root-relative so it is a
// stable, URL-safe identifier regardless of whether run was given a relative
// or absolute root (an absolute path would otherwise break detail lookups).
func (s *apiServer) summarize(e template.ScaffoldEntry) integrationSummary {
	sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
	sum.Path = s.relPath(e.Path)
	path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
	parent := filepath.Dir(path)
	if path == root || parent == root {
		return sum
	}
	sum.System = filepath.Base(parent)
	if grand := filepath.Dir(parent); grand != root {
		sum.Domain = filepath.Base(grand)
	}
	return sum
}

// relPath turns an entry's on-disk path into the root-relative, slash-separated
// identifier used in API responses and URLs. It falls back to the cleaned path
// so a value is always produced even if Rel fails (e.g. differing volumes).
func (s *apiServer) relPath(p string) string {
	if rel, err := filepath.Rel(s.root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

// flow returns every integration enriched with the pipeline steps and Dapr
// components the flow canvas draws, so the whole graph loads in one request.
// It reuses integrationDetail but leaves the document fields (agents/readme)
// nil — the canvas nodes do not render them.
func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
	entries, _ := template.ListScaffolds(s.root)
	nodes := make([]integrationDetail, 0, len(entries))
	for _, e := range entries {
		dir := e.Path
		nodes = append(nodes, integrationDetail{
			integrationSummary: s.summarize(e),
			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
		})
	}
	writeJSON(w, http.StatusOK, nodes)
}

func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
	want := strings.Trim(r.PathValue("path"), "/")
	entries, _ := template.ListScaffolds(s.root)
	for _, e := range entries {
		if s.relPath(e.Path) == want {
			writeJSON(w, http.StatusOK, s.enrich(e))
			return
		}
	}
	writeError(w, http.StatusNotFound, "integration not found: "+want)
}

// enrich reads optional on-disk context for an integration. The entry's Path
// is already usable from the process working directory (see ListScaffolds), so
// it doubles as the project directory.
func (s *apiServer) enrich(e template.ScaffoldEntry) integrationDetail {
	dir := e.Path
	return integrationDetail{
		integrationSummary: s.summarize(e),
		Agents:             readDoc(dir, "AGENTS.md"),
		Readme:             readDoc(dir, "README.md"),
		Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
		PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
	}
}

// readDoc returns the named text file's (possibly truncated) contents, or nil
// if it is absent or unreadable.
func readDoc(dir, name string) *fileDoc {
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		return nil
	}
	if len(data) > maxDocBytes {
		data = data[:maxDocBytes]
	}
	return &fileDoc{Name: name, Content: string(data)}
}

// listNames returns the sorted base names of the files directly under dir, or
// nil if dir is absent or unreadable.
func listNames(dir string) []string {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var names []string
	for _, ent := range ents {
		if !ent.IsDir() {
			names = append(names, ent.Name())
		}
	}
	sort.Strings(names)
	return names
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	_ = enc.Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// DataFlowLabel is the template.yaml metadata label a template uses to
	// declare which way data crosses the system boundary for integrations
	// scaffolded from it: "in", "out", "both" or "internal".
	DataFlowLabel = "intropy.dev/data-flow"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g.
// `manifests create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int    `json:"schemaVersion"`
	Template      string `json:"template"` // directory name in the template library repo
	Owner         string `json:"owner"`
	Repo          string `json:"repo"`
	Version       string `json:"version"`
	// DataFlow records which way data crosses the system boundary, copied
	// from the template's DataFlowLabel at create time: "in", "out", "both"
	// or "internal". Empty when the template does not declare it; consumers
	// fall back to their own heuristics (additive field, no schema bump).
	DataFlow string         `json:"dataFlow,omitempty"`
	Values   map[string]any `json:"values"`
}

// dataFlowFromLabels returns the validated data-flow declaration from a
// template's metadata labels, or "" when absent or not one of the known
// values — an unrecognized declaration is surfaced as unknown, not guessed.
func dataFlowFromLabels(labels map[string]string) string {
	switch v := labels[DataFlowLabel]; v {
	case "in", "out", "both", "internal":
		return v
	default:
		return ""
	}
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}
